" fill=""black""/>
</svg>";
    
    var result = SixSvg
      .FromString(svgString)
      .Query()
      .CleanupAttributes()
      .CollapseGroups()
      .RemoveEmptyAttributes()
      .RemoveEmptyNodes()
      .RemoveEmptyText()
      .RemoveEmptyContainers()
      .RoundPathSegments(2)
      .CompressOutput()
      .Build()
      .SizeComparisonInPercentage(percentage =>
      {
        Console.WriteLine($"Percentage of size reduction: {percentage} %");
      })
      .SizeComparisonInBytes((before, after) =>
      {
        Console.WriteLine($"Byte size before: {before}");
        Console.WriteLine($"Byte size after: {after}");
      });
  
  
    // Save the optimized SVG to a file as svg and bitmap formats
    result.ModifiedSvg.ToSvgFile($"{savePath}.svg");
    result.ModifiedSvg.ToBitmapFile(MagickFormat.Png24, $"{savePath}.webp", 256, 256);
    result.ModifiedSvg.ToBitmapFile(MagickFormat.WebP, $"{savePath}.webp", 256, 256);
    
    Console.WriteLine($"SVG string is: {result.ModifiedSvg.ToSvg()}");
  }
}